import path from 'path';

/**
 * Resolve a relative path below the workspace root and return the absolute result as a string.
 *
 * @param {string} root - The workspace root path.
 * @param {string} value - The path to resolve, which may be relative or absolute.
 * @returns {string} The absolute resolved path.
 * @throws {Error} If `value` is an absolute path or if it escapes the workspace root.
 */
export function resolveRelative(root, value) {
  // Reject absolute paths
  if (path.isAbsolute(value)) {
    throw new Error(`Path escapes the workspace: ${value}`);
  }

  // Resolve to an absolute path based on the root
  const resolved = path.resolve(root, value);

  // Determine if the resolved path is still within the root
  const relative = path.relative(root, resolved);
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    throw new Error(`Path escapes the workspace: ${value}`);
  }

  return resolved;
}

import { resolveRelative } from './src/lib.mjs';

const root = '/workspace';
const cases = [
  {value: 'a/b', expect: '/workspace/a/b'},
  {value: './a', expect: '/workspace/a'},
  {value: '../outside', expectError: true},
  {value: '/abs', expectError: true},
  {value: 'nested/../file', expect: '/workspace/file'},
];

cases.forEach(({value, expect, expectError})=>{
  try {
    const res = resolveRelative(root, value);
    if(expectError){ console.error('Expected error for', value,'but got',res); }
    else if(res!==expect){ console.error('Mismatch:', value,'=>',res,'expected',expect); }
    else console.log('✓', value);
  } catch(e){
    if(expectError){ console.log('✓', value,'error thrown as expected');}
    else console.error('Error for', value,':',e.message);
  }
});
